sp_widget.client_script:
function($scope, $rootScope, spUtil, $timeout) {
  $scope.anoSelecionado = null;
  $scope.dadosVisiveis = null;
  $scope.isFading = false;

  function carregarDados(ano) {
    $scope.isFading = true; // inicia fade-out visual

    // espera o fade-out terminar (500ms conforme CSS)
    $timeout(function() {
      var params = {};
      if (ano) {
        params.filtro_ano = ano;
      }

      spUtil.get('rcl_total_ano_card_1', params).then(function(response) {
        if (response.data && response.data.dados && response.data.dados.length > 0) {
          $scope.dadosVisiveis = response.data.dados[0];
          $scope.anoSelecionado = $scope.dadosVisiveis.ano;
        } else {
          $scope.dadosVisiveis = null;
          $scope.anoSelecionado = null;
        }

        // pequeno delay para aplicar o fade-in
        $timeout(function() {
          $scope.isFading = false; // fade-in
        }, 50);
      });
    }, 500);
  }

  // Carrega inicialmente
  carregarDados(null);

  // Ouve evento
  $rootScope.$on('anoSelecionado', function(evt, ano) {
    carregarDados(ano);
  });
}

sp_widget.css:
/* --- 1. Importação da Fonte --- */
@import url('https://fonts.googleapis.com/css2?family=Roboto+Flex:opsz,wght@8..144,100..1000&display=swap');

/* --- 2. Wrapper Principal (Controla Animação e Layout Externo) --- */
.financial-widget-wrapper {
  font-family: 'Roboto Flex', sans-serif;
  margin-top: 4rem; /* Margem original do seu Código 2 */

  /* Propriedades de Transição (Do Código 1) */
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
  transition: opacity 0.5s ease-in-out, transform 0.5s ease-in-out, visibility 0.5s ease-in-out;
}

/* Estado quando o widget está recarregando (Fade Out) */
.financial-widget-wrapper.fade-out {
  opacity: 0;
  visibility: hidden;
  transform: translateY(20px);
}

/* --- 3. Estrutura do Widget (Visual do Código 2) --- */
.financial-widget {
  border: 1px solid #ccc;
  border-radius: 4px;
  overflow: hidden;
  background-color: #fff; /* Garante fundo branco */
}

.indicator-block {
  text-align: center;
  padding: 0;
}

.indicator-header {
  background-color: #EBEDF1;
  color: #021770;
  font-weight: 400;
  padding: 8px 10px;
  font-size: 14px;
  border-bottom: 1px solid #C7C7C7;
  font-family: 'Roboto Flex', sans-serif;
}

.indicator-value {
  color: #021770;
  font-size: 32px;
  font-weight: 400;
  padding: 10px 10px 15px;
  font-family: 'Roboto Flex', sans-serif;
}

/* Classe utilitária para quando a mensagem for texto (sem dados) */
.indicator-value.small-text {
  font-size: 18px;
  color: #666;
  line-height: 1.5;
  padding: 20px;
}

/* --- 4. Responsividade (Adaptado do Código 1 para o Estilo do 2) --- */

/* Telas Pequenas (Mobile - até 767px) */
@media (max-width: 767px) {
  .financial-widget-wrapper {
    margin-top: 1rem; /* Margem menor em mobile */
  }

  .indicator-value {
    font-size: 24px; /* Fonte levemente menor */
  }
}

/* Tablets (768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  .financial-widget-wrapper {
    margin-top: 2rem;
  }
}

/* Galaxy Z Fold 5 e dispositivos muito estreitos */
@media (max-width: 350px) {
  .indicator-header {
    font-size: 12px;
  }
  .indicator-value {
    font-size: 20px;
    padding: 6px;
  }
}

sp_widget.script:
(function() {
  // Função para formatar número no padrão brasileiro: 1.234.567,89
  /* function formatarNumero(valor) {
  var resultado = (valor);
  resultado = resultado.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return resultado;
}*/
	 function formatarNumero(valor) {
  if (typeof valor !== 'number') {
    valor = parseFloat(valor);
  }

  return valor.toFixed(2) // fixa duas casas decimais
              .replace('.', ',') // troca ponto decimal por vírgula
              .replace(/\B(?=(\d{3})+(?!\d))/g, '.'); // separador de milhar
}

  // Pega o ano filtrado ou o último ano
  var anoFiltrado = input && input.filtro_ano ? input.filtro_ano : null;
  if (!anoFiltrado) {
    var grAno = new GlideRecord('x_sded9_portal_t_0_u_rreo');
    grAno.orderByDesc('u_ano');
    grAno.setLimit(1);
    grAno.query();
    if (!grAno.next()) {
      data.temDado = false;
      data.ano = null;
      data.dados = [];
      return;
    }
    anoFiltrado = grAno.getValue('u_ano');
  }

  // Soma valores do ano filtrado
  var grSoma = new GlideRecord('x_sded9_portal_t_0_u_rreo');
  grSoma.addQuery('u_ano', anoFiltrado);
  grSoma.query();

  var soma = 0;
  while (grSoma.next()) {
    soma += parseFloat(grSoma.getValue('rreo_according_to_lrf_fiscal_responsibility_law_2')) || 0;
  }


  if (soma >= 0) {
    var valorFormatado = formatarNumero(soma);
		//gs.addInfoMessage(valorFormatado)

    data.temDado = true;
    data.valorSoma = soma;
    data.valorSomaFormatado = valorFormatado;
    data.ano = anoFiltrado;
    data.dados = [{
      ano: anoFiltrado,
      valorSoma: soma,
      valorSomaFormatado: valorFormatado,
      temDado: true
    }];
  } else {
    data.temDado = false;
    data.ano = anoFiltrado;
    data.dados = [{
      ano: anoFiltrado,
      valorSoma: 0,
      valorSomaFormatado: '0,00',
      temDado: false
    }];
  }
})();
